55	     * 须在已持有 repository_state 行锁的事务内调用。
56	     */
57	    public RepositorySnapshot loadSnapshot() {
58	        List<ArtifactRow> rows = jdbcTemplate.query(
59	                "SELECT id, name, version, withdrawn FROM artifact ORDER BY name ASC, version DESC",
60	                (rs, n) -> new ArtifactRow(rs.getLong("id"), rs.getString("name"),
61	                        rs.getInt("version"), rs.getInt("withdrawn") == 1));
62	
63	        List<DepRow> depRows = jdbcTemplate.query(
64	                "SELECT artifact_id, name, minimum_version, maximum_version FROM artifact_dependency",
65	                (rs, n) -> new DepRow(rs.getLong("artifact_id"), rs.getString("name"),
66	                        rs.getInt("minimum_version"), rs.getInt("maximum_version")));
67	        Map<Long, List<DependencyRange>> depsByArtifact = depRows.stream()
68	                .collect(Collectors.groupingBy(DepRow::artifactId,
69	                        Collectors.mapping(d -> new DependencyRange(d.name(), d.minimumVersion(), d.maximumVersion()),
70	                                Collectors.toList())));
71	
72	        Map<String, List<ArtifactVersion>> artifacts = new LinkedHashMap<>();
73	        for (ArtifactRow row : rows) {
74	            List<DependencyRange> deps = depsByArtifact.getOrDefault(row.id(), List.of());
75	            ArtifactVersion version = new ArtifactVersion(row.id(), row.name(), row.version(),
76	                    row.withdrawn(), List.copyOf(deps));
77	            artifacts.computeIfAbsent(row.name(), k -> new ArrayList<>()).add(version);
78	        }
79	        return new RepositorySnapshot(getRepositoryVersion(), Map.copyOf(artifacts));
80	    }
81	
82	    /** name+version 的制品版本是否已存在（含撤回版本）。 */
83	    public boolean artifactExists(String name, int version) {
84	        Integer count = jdbcTemplate.queryForObject(
85	                "SELECT COUNT(1) FROM artifact WHERE name = ? AND version = ?",
86	                Integer.class, name, version);
87	        return count != null && count > 0;
88	    }
