1	package com.example.starter.domain;
2	
3	import java.util.List;
4	import java.util.Map;
5	import java.util.TreeMap;
6	
7	/**
8	 * 依赖锁定解析器：在一致性仓库快照上带回溯地求解精确版本组合。
9	 *
10	 * <p>规则：根版本固定；其余名称按字典序选择下一个尚未解析的依赖，
11	 * 候选版本从高到低尝试，遇冲突回退，取首个完整可行结果。
12	 * 已选制品之间必须互相满足区间约束，因此依赖图存在环时也会被正确校验。
13	 */
14	public final class LockResolver {
15	
16	    private LockResolver() {
17	    }
18	
19	    /**
20	     * 求解锁定组合。
21	     *
22	     * @param snapshot    一致性仓库快照（每名称版本按版本号降序）
23	     * @param rootName    根制品名称
24	     * @param rootVersion 根制品精确版本（必须存在且未撤回，由调用方保证）
25	     * @return 名称 -> 精确版本（名称升序）；全部组合不可行时返回 null
26	     */
27	    public static Map<String, Integer> resolve(RepositorySnapshot snapshot,
28	                                               String rootName, int rootVersion) {
29	        Map<String, List<ArtifactVersion>> all = snapshot.artifacts();
30	        List<ArtifactVersion> rootCandidates = all.get(rootName);
31	        if (rootCandidates == null) {
32	            throw new IllegalArgumentException("根制品不存在: " + rootName);
33	        }
34	        ArtifactVersion root = rootCandidates.stream()
35	                .filter(a -> a.version() == rootVersion && !a.withdrawn())
36	                .findFirst()
37	                .orElseThrow(() -> new IllegalArgumentException(
38	                        "根制品版本不存在或已撤回: " + rootName + ":" + rootVersion));
39	
40	        TreeMap<String, ArtifactVersion> chosen = new TreeMap<>();
41	        chosen.put(rootName, root);
42	        // 根可能自依赖：固定版本也必须落在自身声明的区间内。
43	        if (!satisfiesChosen(root, chosen)) {
44	            return null;
45	        }
46	        if (solve(all, chosen)) {
47	            TreeMap<String, Integer> result = new TreeMap<>();
48	            chosen.forEach((name, artifact) -> result.put(name, artifact.version()));
49	            return result;
50	        }
51	        return null;
52	    }
53	
54	    /**
55	     * 递归回溯：选出字典序最小的未解析依赖名称，从高到低尝试候选版本。
56	     */
57	    private static boolean solve(Map<String, List<ArtifactVersion>> all,
58	                                 TreeMap<String, ArtifactVersion> chosen) {
59	        // 汇总所有已选制品对“尚未解析名称”的区间约束，取交集。
60	        String next = null;
61	        int lo = Integer.MAX_VALUE;
62	        int hi = Integer.MIN_VALUE;
63	        for (ArtifactVersion artifact : chosen.values()) {
64	            for (DependencyRange dep : artifact.dependencies()) {
65	                if (chosen.containsKey(dep.name())) {
66	                    continue;
67	                }
68	                if (next == null || dep.name().compareTo(next) < 0) {
69	                    next = dep.name();
70	                    lo = dep.minimumVersion();
71	                    hi = dep.maximumVersion();
72	                } else if (dep.name().equals(next)) {
73	                    lo = Math.max(lo, dep.minimumVersion());
74	                    hi = Math.min(hi, dep.maximumVersion());
75	                }
76	            }
77	        }
78	
79	        if (next == null) {
80	            // 所有依赖均已解析为精确版本。
81	            return true;
82	        }
83	        if (lo > hi) {
84	            // 多个已选制品对该名称的区间交集为空。
85	            return false;
86	        }
87	
88	        // 候选从高到低（快照已按版本号降序），跳过撤回版本和区间外版本。
89	        List<ArtifactVersion> candidates = all.getOrDefault(next, List.of());
90	        for (ArtifactVersion candidate : candidates) {
91	            if (candidate.withdrawn() || candidate.version() < lo || candidate.version() > hi) {
92	                continue;
93	            }
94	            // 新候选对所有已选名称（含自身）的区间必须成立；环依赖在此被校验。
95	            if (!satisfiesChosen(candidate, chosen)) {
96	                continue;
97	            }
98	            chosen.put(next, candidate);
99	            if (solve(all, chosen)) {
100	                return true;
101	            }
102	            chosen.remove(next);
103	        }
104	        return false;
105	    }
106	
107	    /**
108	     * 校验候选制品声明的、指向已选名称的依赖区间均被已选精确版本满足。
109	     */
110	    private static boolean satisfiesChosen(ArtifactVersion candidate,
111	                                           Map<String, ArtifactVersion> chosen) {
112	        for (DependencyRange dep : candidate.dependencies()) {
113	            ArtifactVersion selected = chosen.get(dep.name());
114	            if (selected == null) {
115	                continue;
116	            }
117	            if (selected.version() < dep.minimumVersion() || selected.version() > dep.maximumVersion()) {
118	                return false;
119	            }
120	        }
121	        return true;
