package com.example.starter.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;

import java.time.Instant;

/**
 * 弃用窗口登记项：某制品版本的生效 UTC 时刻、同制品替代版本与说明。
 *
 * @param effectiveAt 弃用生效时刻（UTC，左闭：到达即生效），不得早于登记时刻
 * @param replacementVersion 同制品的替代版本号，必须已登记且未撤回
 * @param reason 弃用说明，可为 null（未填写）
 */
public record DeprecationSpec(
        @NotBlank String name,
        @Positive int version,
        @NotNull Instant effectiveAt,
        @Positive int replacementVersion,
        @Size(max = 512) String reason) {
}

package com.example.starter.api.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 批量登记弃用窗口请求：先校验完整替代图，任一失败整次不写入。
 */
public record BatchDeprecationRequest(
        @NotNull @Size(min = 1, max = 20) List<@Valid DeprecationSpec> windows) {

    public BatchDeprecationRequest {
        if (windows != null) {
            windows = List.copyOf(windows);
        }
    }
}

package com.example.starter.api.dto;

import java.util.List;

/**
 * 批量登记弃用窗口响应。
 *
 * @param repositoryVersion 本次批量登记完成后的仓库版本号
 * @param windows 已登记的弃用窗口，按请求顺序返回
 */
public record BatchDeprecationResponse(
        long repositoryVersion,
        List<DeprecationResponse> windows) {
}

package com.example.starter.api.dto;

/**
 * 撤销弃用窗口响应。
 *
 * @param repositoryVersion 本次撤销完成后的仓库版本号
 * @param window 撤销后的窗口视图（revoked=true，revokedAt 已固化）
 */
public record RevokeDeprecationResponse(
        long repositoryVersion,
        DeprecationResponse window) {
}

package com.example.starter.api.dto;

import java.time.Instant;

/**
 * 锁定时刻固化的弃用警告快照（含替代建议），后续弃用变更不改写。
 *
 * @param replacementVersion 锁定时刻窗口登记的同制品替代版本号
 * @param effectiveAt 锁定时刻窗口登记的弃用生效时刻（UTC）
 * @param reason 锁定时刻窗口登记的弃用说明；null 表示未填写
 */
public record DeprecationWarningView(
        String name,
        int version,
        int replacementVersion,
        Instant effectiveAt,
        String reason) {
}

package com.example.starter.api.dto;

import java.time.Instant;

/**
 * 锁定 422 响应中的已生效弃用条目明细（按名称、版本稳定排序）。
 *
 * @param replacementVersion 同制品替代版本号
 * @param effectiveAt 弃用生效时刻（UTC，左闭）
 */
public record DeprecatedClosureItem(
        String name,
        int version,
        int replacementVersion,
        Instant effectiveAt) {
}

package com.example.starter.api.dto;

import java.time.Instant;
import java.util.List;

/**
 * 弃用窗口诊断视图：按查询时刻的实际状态计数，读取不改变状态。
 *
 * @param now 诊断时刻（UTC）
 * @param total 窗口总数（含已撤销）
 * @param pending 尚未生效的有效窗口数（now &lt; effectiveAt）
 * @param effective 已生效的有效窗口数（now &gt;= effectiveAt，左闭）
 * @param revoked 已撤销窗口数
 * @param effectiveWindows 当前已生效窗口明细，按名称、版本升序
 */
public record DeprecationDiagnosticsResponse(
        Instant now,
        int total,
        int pending,
        int effective,
        int revoked,
        List<DeprecationResponse> effectiveWindows) {
}

