package com.example.starter.api.dto;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 统一错误响应体。
 *
 * @param details 可选的结构化明细（如锁定 422 的已生效弃用条目列表）；null 时不出现在响应中
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record ApiError(String error, String message, Object details) {

    public ApiError(String error, String message) {
        this(error, message, null);
    }
}

package com.example.starter.support;

/**
 * 业务 API 异常，携带 HTTP 状态码、错误码与可选结构化明细。
 */
public class ApiException extends RuntimeException {

    private final int status;
    private final String code;
    private final Object details;

    public ApiException(int status, String code, String message) {
        this(status, code, message, null);
    }

    public ApiException(int status, String code, String message, Object details) {
        super(message);
        this.status = status;
        this.code = code;
        this.details = details;
    }

    public int getStatus() {
        return status;
    }

    public String getCode() {
        return code;
    }

    /** 结构化错误明细（如已生效弃用条目列表），无明细时为 null。 */
    public Object getDetails() {
        return details;
    }

    public static ApiException badRequest(String message) {
        return new ApiException(400, "BAD_REQUEST", message);
    }

    public static ApiException notFound(String message) {
        return new ApiException(404, "NOT_FOUND", message);
    }

    public static ApiException conflict(String message) {
        return new ApiException(409, "CONFLICT", message);
    }

    public static ApiException unprocessable(String message) {
        return new ApiException(422, "UNPROCESSABLE_ENTITY", message);
    }

    /** 携带结构化明细的 422。 */
    public static ApiException unprocessable(String message, Object details) {
        return new ApiException(422, "UNPROCESSABLE_ENTITY", message, details);
    }
}

package com.example.starter.api.dto;

import java.time.Instant;
import java.util.List;

/**
 * 历史锁文件视图，entries 按名称升序排列。
 *
 * @param createdAt 锁定解析时刻（UTC），锁定成功即固化，后续弃用变更不改写
 * @param deprecationWarnings 锁定时刻命中的弃用警告与替代建议快照，按名称升序
 */
public record LockFileResponse(
        long id,
        String rootName,
        int rootVersion,
        long repositoryVersion,
        Instant createdAt,
        List<LockEntryResponse> entries,
        List<DeprecationWarningView> deprecationWarnings) {
}

