    return specs.stream()
            .map(s -> s.name().trim() + ":" + s.version() + ":" + s.effectiveAt()
                    + ":" + s.replacementVersion() + ":" + (s.reason() == null ? "" : s.reason()))
            .sorted()
            .reduce((a, b) -> a + "," + b)
            .orElse("");
}

